package com.internal.ops

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.io.BufferedReader
import java.io.InputStreamReader

@Serializable
data class DiagnosticRequest(
    val target: String,
    val timeout: Int = 5,
    val packetCount: Int = 4
)

@Serializable
data class DiagnosticResponse(
    val output: String,
    val exitCode: Int,
    val timestamp: Long
)

fun Application.module() {
    routing {
        // Health check endpoint
        get("/health") {
            call.respondText("OK", ContentType.Text.Plain)
        }

        // Internal network diagnostic tool for SRE team
        post("/api/v1/diagnostics/ping") {
            val body = call.receiveText()
            val request = Json.decodeFromString<DiagnosticRequest>(body)

            // Validate timeout range
            val safeTimeout = request.timeout.coerceIn(1, 30)
            val safePacketCount = request.packetCount.coerceIn(1, 10)

            // Build ping command for network diagnostics
            val command = buildDiagnosticCommand(request.target, safeTimeout, safePacketCount)

            val result = executeCommand(command)

            val response = DiagnosticResponse(
                output = result.first,
                exitCode = result.second,
                timestamp = System.currentTimeMillis()
            )

            call.respondText(
                Json.encodeToString(DiagnosticResponse.serializer(), response),
                ContentType.Application.Json
            )
        }

        // DNS lookup utility
        post("/api/v1/diagnostics/resolve") {
            val body = call.receiveText()
            val hostname = Json.parseToJsonElement(body)
                .jsonObject["hostname"]?.jsonPrimitive?.content ?: ""

            val command = "nslookup $hostname"
            val result = executeCommand(command)

            call.respondText(
                Json.encodeToString(DiagnosticResponse.serializer(),
                    DiagnosticResponse(result.first, result.second, System.currentTimeMillis())
                ),
                ContentType.Application.Json
            )
        }
    }
}

fun buildDiagnosticCommand(target: String, timeout: Int, count: Int): String {
    // Determine OS for correct ping syntax
    val os = System.getProperty("os.name").lowercase()
    return if (os.contains("win")) {
        "ping -n $count -w ${timeout * 1000} $target"
    } else {
        "ping -c $count -W $timeout $target"
    }
}

fun executeCommand(command: String): Pair<String, Int> {
    return try {
        val process = Runtime.getRuntime().exec(arrayOf("/bin/sh", "-c", command))
        val reader = BufferedReader(InputStreamReader(process.inputStream))
        val errorReader = BufferedReader(InputStreamReader(process.errorStream))

        val output = StringBuilder()
        reader.forEachLine { output.appendLine(it) }
        errorReader.forEachLine { output.appendLine(it) }

        val exitCode = process.waitFor()
        Pair(output.toString().take(4096), exitCode)
    } catch (e: Exception) {
        Pair("Error: ${e.message}", -1)
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}
